1	/**
2	 * <ds-select> — a token-driven single-choice select.
3	 *
4	 * The label, hint, and error live in the shadow root so their association does
5	 * not depend on light-DOM ids. The element is form-associated: name and value
6	 * participate in submit and reset across the shadow boundary.
7	 */
8	
9	// Generated from src/select.css by build-styles.js (run `pnpm run build`).
10	import { styles } from "../dist/select.styles.js";
11	import {
12	  Base,
13	  ForwardsFocus,
14	  defineElement,
15	  focusTarget,
16	  lazyStyleSheet,
17	} from "./internal/element.js";
18	
19	const VALIDITY_FLAGS = [
20	  "badInput",
21	  "patternMismatch",
22	  "rangeOverflow",
23	  "rangeUnderflow",
24	  "stepMismatch",
25	  "tooLong",
26	  "tooShort",
27	  "typeMismatch",
28	  "valueMissing",
29	];
30	
31	const styleSheet = lazyStyleSheet(styles);
32	
33	export class DsSelect extends ForwardsFocus(Base) {
34	  /** Lets ElementInternals submit the value across the shadow boundary. */
35	  static formAssociated = true;
36	
37	  static observedAttributes = ["disabled", "error", "hint", "label", "name", "required", "value"];
38	
39	  #internals;
40	  #field;
41	  #label;
42	  #labelText;
43	  #requiredMark;
44	  #input;
45	  #hint;
46	  #error;
47	  #formDisabled = false;
48	  #dirty = false;
49	  #observer;
50	  #pendingValue;
51	
52	  constructor() {
53	    super();
54	    this.#internals = this.attachInternals();
55	
56	    const root = this.attachShadow({ mode: "open" });
57	    root.adoptedStyleSheets = [styleSheet()];
58	    root.innerHTML = `
59	      <div class="field" part="field">
60	        <label class="label" part="label" for="control">
61	          <span class="label-text"></span>
62	          <span class="required" hidden aria-hidden="true">*</span>
63	        </label>
64	        <select id="control" class="control" part="control"></select>
65	        <p id="hint" class="hint" part="hint" hidden></p>
66	        <p id="error" class="error" part="error" hidden aria-live="polite"></p>
67	      </div>
68	    `;
69	
70	    this.#field = root.querySelector(".field");
71	    this.#label = root.querySelector("label");
72	    this.#labelText = root.querySelector(".label-text");
73	    this.#requiredMark = root.querySelector(".required");
74	    this.#input = root.querySelector("select");
75	    this.#hint = root.querySelector("#hint");
76	    this.#error = root.querySelector("#error");
77	
78	    this.#input.addEventListener("input", this.#onInput);
79	    this.#input.addEventListener("change", this.#onChange);
80	    this.#input.addEventListener("invalid", this.#onInvalid);
81	    this.addEventListener("invalid", this.#onInvalid);
82	
83	    this.#render();
84	    this.#syncDisabled();
85	    this.#syncFormValue();
86	    this.#syncValidity();
87	  }
88	
89	  connectedCallback() {
90	    this.#observer ??= new MutationObserver(() => this.#syncOptions());
91	    this.#observer.observe(this, {
92	      childList: true,
93	      subtree: true,
94	      attributes: true,
95	      characterData: true,
96	    });
97	    this.#syncOptions();
98	  }
99	
100	  disconnectedCallback() {
101	    this.#observer?.disconnect();
102	  }
103	
104	  #syncOptions(reset = false) {
105	    const current = reset
106	      ? null
107	      : (this.#pendingValue ?? (this.#input.options.length ? this.#input.value : null));
108	    const choices = [...this.children].filter(
109	      (child) => child.localName === "option" || child.localName === "optgroup",
110	    );
111	    this.#input.replaceChildren(...choices.map((choice) => choice.cloneNode(true)));
112	    if (current != null && [...this.#input.options].some((option) => option.value === current)) {
113	      this.#input.value = current;
114	      this.#pendingValue = undefined;
115	    } else if (!this.#dirty && this.hasAttribute("value")) {
116	      this.#input.value = this.getAttribute("value");
117	    }
118	    if (this.#input.options.length) this.#pendingValue = undefined;
119	    this.#syncFormValue();
120	    this.#syncValidity();
121	  }
122	
123	  attributeChangedCallback(name, _old, value) {
124	    if (!this.#input) return;
125	
126	    if (name === "value") {
127	      if (!this.#dirty) {
128	        this.#pendingValue = value ?? "";
129	        this.#input.value = value ?? "";
130	        this.#syncFormValue();
131	      }
132	      this.#syncValidity();
133	      return;
134	    }
135	
136	    this.#render();
137	    if (name === "disabled") this.#syncDisabled();
138	    this.#syncFormValue();
139	    this.#syncValidity();
140	  }
141	
142	  /** Mirrors disabled state inherited from an ancestor <fieldset>. */
143	  formDisabledCallback(disabled) {
144	    this.#formDisabled = disabled;
145	    this.#syncDisabled();
146	  }
147	
148	  formResetCallback() {
149	    this.#dirty = false;
150	    this.#pendingValue = undefined;
151	    this.#syncOptions(true);
152	    this.#syncFormValue();
153	    this.#syncValidity();
154	  }
155	
156	  formStateRestoreCallback(state, mode) {
157	    if (typeof state !== "string") return;
158	    this.#pendingValue = state;
159	    this.#input.value = state;
160	    this.#dirty = mode === "restore";
161	    this.#syncFormValue();
162	    this.#syncValidity();
163	  }
164	
165	  get [focusTarget]() {
166	    return this.#input;
167	  }
168	
169	  /** The <form> this field belongs to, or null. */
170	  get form() {
171	    return this.#internals.form;
172	  }
173	
174	  get label() {
175	    return this.getAttribute("label") ?? "";
176	  }
177	
178	  set label(value) {
179	    this.setAttribute("label", value ?? "");
180	  }
181	
182	  get hint() {
183	    return this.getAttribute("hint") ?? "";
184	  }
185	
186	  set hint(value) {
187	    this.#setOptionalAttribute("hint", value);
188	  }
189	
190	  get error() {
191	    return this.getAttribute("error") ?? "";
192	  }
193	
194	  set error(value) {
195	    this.#setOptionalAttribute("error", value);
196	  }
197	
198	  get name() {
199	    return this.getAttribute("name") ?? "";
200	  }
201	
202	  set name(value) {
203	    this.#setOptionalAttribute("name", value);
204	  }
205	
206	  get disabled() {
207	    return this.hasAttribute("disabled");
208	  }
209	
210	  set disabled(value) {
211	    this.toggleAttribute("disabled", Boolean(value));
212	  }
213	
214	  get required() {
215	    return this.hasAttribute("required");
216	  }
217	
218	  set required(value) {
219	    this.toggleAttribute("required", Boolean(value));
220	  }
221	
222	  get value() {
223	    return this.#input ? this.#input.value : (this.getAttribute("value") ?? "");
224	  }
225	
226	  set value(next) {
227	    const text = next == null ? "" : String(next);
228	    this.#dirty = true;
229	    if (!this.#input) return;
230	    this.#pendingValue = text;
231	    this.#input.value = text;
232	    this.#syncFormValue();
233	    this.#syncValidity();
234	  }
235	
236	  #setOptionalAttribute(name, value) {
237	    if (value == null || value === "") this.removeAttribute(name);
238	    else this.setAttribute(name, value);
239	  }
240	
241	  #render() {
242	    const label = this.label;
243	    this.#labelText.textContent = label;
244	    this.#label.hidden = label.length === 0;
245	
246	    const hint = this.hint;
247	    this.#hint.textContent = hint;
248	    this.#hint.hidden = hint.length === 0;
249	
250	    const error = this.error;
251	    this.#error.textContent = error;
252	    this.#error.hidden = error.length === 0;
253	
254	    this.#requiredMark.hidden = !this.required;
255	    this.#input.required = this.required;
256	    const describedBy = [];
257	    if (hint) describedBy.push("hint");
258	    if (error) describedBy.push("error");
259	    if (describedBy.length > 0) this.#input.setAttribute("aria-describedby", describedBy.join(" "));
260	    else this.#input.removeAttribute("aria-describedby");
261	
262	    if (error) this.#input.setAttribute("aria-invalid", "true");
263	    else this.#input.removeAttribute("aria-invalid");
264	  }
265	
266	  #syncDisabled() {
267	    const disabled = this.disabled || this.#formDisabled;
268	    this.#input.disabled = disabled;
269	    this.#field.classList.toggle("is-disabled", disabled);
270	    this.#syncFormValue();
271	    this.#syncValidity();
272	  }
273	
274	  #syncFormValue() {
275	    if (this.disabled || this.#formDisabled) {
276	      this.#internals.setFormValue(null);
277	      return;
278	    }
279	    const option = this.#input.selectedOptions[0];
280	    const unavailable =
281	      !option ||
282	      option.disabled ||
283	      (option.parentElement.localName === "optgroup" && option.parentElement.disabled);
284	    this.#internals.setFormValue(unavailable ? null : this.#input.value);
285	  }
286	
287	  #syncValidity() {
288	    const input = this.#input;
289	    const error = this.error;
290	    if (error) {
291	      this.#internals.setValidity({ customError: true }, error, input);
292	      return;
293	    }
294	    if (input.validity.valid) {
295	      this.#internals.setValidity({});
296	      return;
297	    }
298	    const flags = {};
299	    for (const flag of VALIDITY_FLAGS) {
300	      if (input.validity[flag]) flags[flag] = true;
301	    }
302	    this.#internals.setValidity(flags, input.validationMessage, input);
303	  }
304	
305	  #onInput = () => {
306	    this.#dirty = true;
307	    this.#pendingValue = undefined;
308	    this.#syncFormValue();
309	    this.#syncValidity();
310	  };
311	
312	  /**
313	   * The native input's `input` event is composed and reaches the host on its
314	   * own; `change` is not, so re-dispatch it from the host.
315	   */
316	  #onChange = () => {
317	    this.#dirty = true;
318	    this.#pendingValue = undefined;
319	    this.#syncFormValue();
320	    this.#syncValidity();
321	    this.dispatchEvent(new Event("change", { bubbles: true }));
322	  };
323	
324	  /** Keep the visible error as the only validation message when one is set. */
325	  #onInvalid = (event) => {
326	    if (this.error) event.preventDefault();
327	  };
328	}
